                                    trigger.player.disableSkill('acgn_mengxiangfengyin', result.control);
                                    if (!trigger.player.mxfy) {
                                        trigger.player.mxfy = [];
                                    }
                                    event.skill = result.control;
                                    var list = ['上家', '下家'];
                                    player
                                        .chooseControl(list, true)
